import { NextResponse } from 'next/server';

let sales = [
    { id: 1, name: "e-CNPJ A1 (1 Ano)", price: 149.90, commission: 45.00, category: "CNPJ", type: "inv_001" },
    { id: 2, name: "e-CPF A3 (3 Anos)", price: 299.00, commission: 90.00, category: "CPF", type: "inv_002" },
    { id: 3, name: "e-Jurídico A1", price: 199.00, commission: 60.00, category: "Específicos", type: "inv_003" },
];

export async function GET() {
    return NextResponse.json(sales);
}

export async function POST(request: Request) {
    const data = await request.json();
    const newProduct = {
        ...data,
        id: Math.floor(Math.random() * 10000)
    };
    sales.push(newProduct);
    return NextResponse.json(newProduct, { status: 201 });
}

export async function PUT(request: Request) {
    const data = await request.json();
    const { id, ...updates } = data;

    const index = sales.findIndex(p => p.id === id);
    if (index === -1) {
        return NextResponse.json({ error: "Product not found" }, { status: 404 });
    }

    sales[index] = { ...sales[index], ...updates };
    return NextResponse.json(sales[index]);
}

export async function DELETE(request: Request) {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    const index = sales.findIndex(p => p.id.toString() === id);
    if (index === -1) {
        return NextResponse.json({ error: "Product not found" }, { status: 404 });
    }

    const deleted = sales.splice(index, 1);
    return NextResponse.json(deleted[0]);
}
